    const stopDist = cfg.sl * impactMult;

    const bufferDelta = cfg.unit === 'pips' ? bufferDist * cfg.pip : bufferDist;
    const stopDelta = cfg.unit === 'pips' ? stopDist * cfg.pip : stopDist;
